#!/usr/bin/env node
// Builds supabase/setup.sql = migration + seed, for pasting into the Supabase SQL Editor in one go.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";

const migration = readdirSync("supabase/migrations")
  .filter((f) => f.endsWith(".sql"))
  .sort()
  .map((f) => readFileSync(`supabase/migrations/${f}`, "utf8"))
  .join("\n\n");
const seed = readFileSync("supabase/seed.sql", "utf8");
const header = `-- =============================================================================
-- ONE-FILE SETUP (generated by \`npm run db:bundle\` — do not edit by hand)
-- Supabase Dashboard → SQL Editor → New query → paste this whole file → Run.
-- Safe to run more than once.
-- =============================================================================

`;
writeFileSync("supabase/setup.sql", `${header}${migration}\n\n${seed}`);
console.log("✔ supabase/setup.sql written");
